108	    /**
109	     * The owner's salutation: the {@link #getTitle() title} and lastName separated by a single
110	     * space when a title is present, or just the lastName when no title was given.
111	     */
112	    public String getSalutation() {
113	        if (this.title == null || this.title.isEmpty()) {
114	            return this.getLastName();
115	        }
116	        return this.title + " " + this.getLastName();
