140	        this.addressLine2 = addressLine2;
141	    }
142	
143	    public String getCity() {
144	        return this.city;
145	    }
146	
147	    public void setCity(String city) {
148	        this.city = city;
149	    }
150	
151	    public String getPostcode() {
152	        return this.postcode;
153	    }
154	
155	    public void setPostcode(String postcode) {
156	        this.postcode = postcode;
157	    }
158	
159	    public String getTelephone() {
160	        return this.telephone;
161	    }
162	
163	    public void setTelephone(String telephone) {
164	        this.telephone = telephone;
165	    }
166	
167	    public String getEmail() {
168	        return this.email;
169	    }
170	
171	    public void setEmail(String email) {
172	        this.email = email == null ? null : email.toLowerCase();
173	    }
174	
175	    public LocalDate getRegistrationDate() {
176	        return this.registrationDate;
177	    }
178	
179	    public void setRegistrationDate(LocalDate registrationDate) {
180	        this.registrationDate = registrationDate;
181	    }
182	
183	    public LocalDate getBirthDate() {
184	        return this.birthDate;
185	    }
186	
187	    public void setBirthDate(LocalDate birthDate) {
188	        this.birthDate = birthDate;
189	    }
190	
191	    /**
192	     * The owner's age band derived from {@link #birthDate} relative to the
193	     * {@link #registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
194	     * and {@code 'SENIOR'} at 65 or older. Returns {@code null} when no birthDate is set. The age
195	     * is the number of complete years between the birthDate and the registrationDate (or the
196	     * current date when the registrationDate is not yet set).
197	     */
198	    public String getAgeBand() {
199	        if (this.birthDate == null) {
200	            return null;
201	        }
202	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
203	        int years = Period.between(this.birthDate, reference).getYears();
204	        if (years < 18) {
205	            return "MINOR";
206	        }
207	        if (years < 65) {
208	            return "ADULT";
209	        }
210	        return "SENIOR";
211	    }
212	
213	    public String getCustomerCode() {
214	        return this.customerCode;
215	    }
216	
217	    public void setCustomerCode(String customerCode) {
218	        this.customerCode = customerCode;
219	    }
220	
221	    public String getHouseholdId() {
222	        return this.householdId;
223	    }
224	
225	    public void setHouseholdId(String householdId) {
226	        this.householdId = householdId;
227	    }
228	
229	    public Integer getNamesakeCount() {
230	        return this.namesakeCount;
231	    }
232	
233	    public void setNamesakeCount(Integer namesakeCount) {
234	        this.namesakeCount = namesakeCount;
235	    }
236	
237	    public Boolean getBulkSignupWarning() {
238	        return this.bulkSignupWarning;
239	    }
240	
241	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
242	        this.bulkSignupWarning = bulkSignupWarning;
243	    }
244	
245	    public Integer getHouseholdSize() {
246	        return this.householdSize;
247	    }
248	
249	    public void setHouseholdSize(Integer householdSize) {
250	        this.householdSize = householdSize;
251	    }
252	
253	    public Boolean getPossibleDuplicate() {
254	        return this.possibleDuplicate;
255	    }
256	
257	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
258	        this.possibleDuplicate = possibleDuplicate;
259	    }
260	
261	    public Integer getPossibleDuplicateOf() {
262	        return this.possibleDuplicateOf;
263	    }
264	
265	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
266	        this.possibleDuplicateOf = possibleDuplicateOf;
267	    }
268	
269	    /**
270	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
271	     */
272	    public String getDisplayName() {
273	        return this.getLastName() + ", " + this.getFirstName();
274	    }
275	
276	    /**
277	     * The owner's initials: the upper-cased first letters of firstName and lastName,
278	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
279	     */
280	    public String getInitials() {
281	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
282	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
283	    }
284	
285	    /**
286	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
287	     * last two digits of the registrationDate year, e.g. {@code 'NSW-3C1A9F2B-M26'}.
288	     */
289	    public String getMembershipNumber() {
290	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
291	    }
292	
293	    /**
294	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) computed over the decimal digits
295	     * contained in the owner's {@link #customerCode}.
296	     */
297	    public int getCheckDigit() {
298	        return luhnCheckDigit(this.customerCode);
299	    }
300	
301	    /**
302	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
303	     * contained in {@code value}. Reading the digits right to left, every second one is
304	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
305	     * digits are summed, and the check digit is the amount that must be added to that sum to
306	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
307	     * the digit is taken over exactly the digits the string carries.
308	     */
309	    private static int luhnCheckDigit(String value) {
310	        int sum = 0;
311	        boolean doubling = true;
312	        for (int i = value.length() - 1; i >= 0; i--) {
313	            char c = value.charAt(i);
314	            if (c < '0' || c > '9') {
315	                continue;
316	            }
317	            int digit = c - '0';
318	            if (doubling) {
319	                digit *= 2;
320	                if (digit > 9) {
321	                    digit -= 9;
322	                }
323	            }
324	            sum += digit;
325	            doubling = !doubling;
326	        }
327	        return (10 - (sum % 10)) % 10;
328	    }
329	
330	    /** Fixed city-to-region table used to derive an owner's locality. */
331	    private static final Map<String, String> CITY_REGION = Map.of(
332	        "Sydney", "NSW",
333	        "Melbourne", "VIC",
334	        "Brisbane", "QLD");
335	
336	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
337	    public static final String UNKNOWN_REGION = "UNKNOWN";
338	
339	    /**
340	     * The canonical region for a city, derived from the fixed city-to-region table
341	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
342	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
343	     * source of the city-to-region mapping, shared by every rule that is keyed by
344	     * region so the mapping is never re-derived elsewhere.
345	     */
346	    public static String regionOf(String city) {
347	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
348	    }
349	
350	    /**
351	     * The owner's locality: the {@code <REGION>} component of the {@link #getCustomerCode()
352	     * customerCode} (its prefix up to the first {@code '-'}), which is the region derived from
353	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
354	     * known region). Locality is read from the region-and-hash identity so it never re-derives
355	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
356	     */
357	    public String getLocality() {
358	        if (this.customerCode == null) {
359	            return UNKNOWN_REGION;
360	        }
361	        int dash = this.customerCode.indexOf('-');
362	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
363	    }
364	
365	    /** Fixed region-to-timezone table, mapping a region to its IANA timezone name. */
366	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
367	        "NSW", "Australia/Sydney",
368	        "VIC", "Australia/Melbourne",
369	        "QLD", "Australia/Brisbane");
370	
371	    /**
372	     * The owner's timezone: the IANA name for this owner's {@linkplain #getLocality() locality},
373	     * looked up in the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
374	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null} when
375	     * the locality maps to no known region (e.g. {@link #UNKNOWN_REGION}). It reads the locality
376	     * rather than re-deriving a region so the timezone shares the owner's single region identity.
377	     */
378	    public String getTimezone() {
379	        return REGION_TIMEZONE.get(getLocality());
380	    }
381	
382	    /**
383	     * The region derived from this owner's postcode alone: the region whose fixed
384	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
385	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
386	     * component built into the owner's customer code at creation and, through it, the source of the
387	     * owner's {@linkplain #getLocality() locality}. It is the single place a region is read from an
388	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
389	     */
390	    public String getRegion() {
391	        return regionOfPostcode(this.postcode);
392	    }
393	
394	    /**
395	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
396	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
397	     * no known range.
398	     */
399	    private static String regionOfPostcode(String postcode) {
400	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
401	            return null;
402	        }
403	        int value = Integer.parseInt(postcode);
404	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
405	            int[] range = entry.getValue();
406	            if (value >= range[0] && value <= range[1]) {
407	                return entry.getKey();
408	            }
409	        }
410	        return null;
411	    }
412	
413	    /**
414	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
415	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
416	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
417	     */
418	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
419	        "NSW", new int[] {2000, 2099},
420	        "VIC", new int[] {3000, 3099},
421	        "QLD", new int[] {4000, 4099});
422	
423	    /**
424	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
425	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
426	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
427	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
428	     * city with no known region accepts any 4-digit postcode.
429	     */
430	    public boolean isPostcodeValid() {
431	        if (this.postcode == null) {
432	            return true;
433	        }
434	        if (!this.postcode.matches("[0-9]{4}")) {
435	            return false;
436	        }
437	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
438	        if (range == null) {
439	            return true;
440	        }
441	        int value = Integer.parseInt(this.postcode);
442	        return value >= range[0] && value <= range[1];
443	    }
444	
445	    /**
446	     * The national (subscriber) digit count required by each known country calling code, keyed by
447	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
448	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
449	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
450	     * re-derived elsewhere.
451	     */
452	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
453	        "1", 10,
454	        "61", 9);
455	
456	    /**
457	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
458	     * E.164 digit string, choosing the longest matching code known to
459	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
460	     * country code. This is the single place a country code is read from an E.164 number, so every
461	     * rule keyed by that code shares one derivation.
462	     */
463	    private static String countryCodeOf(String e164Digits) {
464	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
465	            .filter(e164Digits::startsWith)
466	            .max(Comparator.comparingInt(String::length))
467	            .orElse(null);
468	    }
469	
470	    /**
471	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
472	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
473	     * known code wins; a number whose country code is not recognised passes this check (its length is
474	     * then governed only by the general E.164 bound), while a recognised code must be followed by
475	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
476	     */
477	    public static boolean hasValidNationalLength(String e164Digits) {
478	        String countryCode = countryCodeOf(e164Digits);
479	        if (countryCode == null) {
480	            return true;
481	        }
482	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
483	    }
484	
485	    /**
486	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
487	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
488	     * gain 3 when the owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. The email,
489	     * namesake and household factors are available on creation; the tenure factor is reached only
490	     * once tenure grows beyond 365 days.
491	     */
492	    public Integer getMembershipPoints() {
493	        int points = 0;
494	        if (hasEmail()) {
495	            points += 2;
496	        }
497	        if (hasNoNamesakes()) {
498	            points += 1;
499	        }
500	        if (hasLargeHousehold()) {
501	            points += 2;
502	        }
503	        if (hasTenureBeyondOneYear()) {
504	            points += 3;
505	        }
506	        return points;
507	    }
508	
509	    /**
510	     * The owner's membership level, a number from 1 to 4 derived from {@linkplain #getMembershipPoints()
511	     * membershipPoints}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or
512	     * more.
513	     */
514	    public Integer getMembershipLevel() {
515	        int points = getMembershipPoints();
516	        if (points >= 6) {
517	            return 4;
518	        }
519	        if (points >= 4) {
520	            return 3;
521	        }
522	        if (points >= 2) {
523	            return 2;
524	        }
525	        return 1;
526	    }
527	
528	    /**
529	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
530	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
531	     * known, is treated as not a large household.
532	     */
533	    private boolean hasLargeHousehold() {
534	        return this.householdSize != null && this.householdSize >= 3;
535	    }
536	
537	    /**
538	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
539	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
540	     * email presence so the check is never re-derived elsewhere.
541	     */
542	    private boolean hasEmail() {
543	        return this.email != null && !this.email.isEmpty();
544	    }
545	
546	    /**
547	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
548	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
549	     * not known, is treated as not unique.
550	     */
551	    private boolean hasNoNamesakes() {
552	        return this.namesakeCount != null && this.namesakeCount == 0;
553	    }
554	
555	    /**
556	     * Whether this owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. A newly created owner
557	     * (zero tenure) does not qualify; the threshold is crossed only once tenure grows beyond one year.
558	     */
559	    private boolean hasTenureBeyondOneYear() {
560	        return this.getTenureDays() > 365;
561	    }
562	
563	    /**
564	     * The owner's tenure in whole days: the number of days between the {@link #registrationDate} and
565	     * the current date, or {@code 0} when the registrationDate is not yet set (a newly created owner has
566	     * zero tenure). Never negative.
567	     */
568	    public long getTenureDays() {
569	        if (this.registrationDate == null) {
570	            return 0;
571	        }
572	        return Math.max(0, ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()));
573	    }
574	
575	    /**
576	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
577	     * otherwise {@code 'PHONE'}.
578	     */
579	    public String getContactPreference() {
580	        return hasEmail() ? "EMAIL" : "PHONE";
581	    }
582	
583	    /**
584	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
585	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
586	     * the national digits grouped into threes from the left separated by spaces,
587	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
588	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
589	     * E.164 form, or carries no known country code.
590	     */
591	    public String getTelephoneDisplay() {
592	        if (this.telephone == null || !this.telephone.startsWith("+")) {
593	            return this.telephone;
594	        }
595	        String digits = this.telephone.substring(1);
596	        String countryCode = countryCodeOf(digits);
597	        if (countryCode == null) {
598	            return this.telephone;
599	        }
600	        String national = digits.substring(countryCode.length());
601	        StringBuilder groups = new StringBuilder();
602	        for (int i = 0; i < national.length(); i += 3) {
603	            if (groups.length() > 0) {
604	                groups.append(' ');
605	            }
606	            groups.append(national, i, Math.min(i + 3, national.length()));
607	        }
608	        return "+" + countryCode + " " + groups;
609	    }
610	
611	    /**
612	     * The owner's identity key: the single derived value used for duplicate detection.
613	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
614	     * empty string when absent) and the householdId (or the empty string when the owner
615	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
616	     * Two owners are duplicates only when their whole identity keys are equal.
617	     */
618	    public String getIdentityKey() {
619	        String telephonePart = this.telephone == null ? "" : this.telephone;
620	        String emailPart = this.email == null ? "" : this.email;
621	        String householdPart = this.householdId == null ? "" : this.householdId;
622	        return telephonePart + "|" + emailPart + "|" + householdPart;
623	    }
624	
625	    protected Set<Pet> getPetsInternal() {
626	        if (this.pets == null) {
627	            this.pets = new HashSet<>();
628	        }
629	        return this.pets;
630	    }
631	
632	    protected void setPetsInternal(Set<Pet> pets) {
633	        this.pets = pets;
634	    }
635	
636	    public List<Pet> getPets() {
637	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
638	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
639	        return Collections.unmodifiableList(sortedPets);
640	    }
641	
642	    public void setPets(List<Pet> pets) {
643	        this.pets = new HashSet<>(pets);
644	    }
645	
646	    public void addPet(Pet pet) {
647	        getPetsInternal().add(pet);
648	        pet.setOwner(this);
649	    }
650	
651	    /**
652	     * Return the Pet with the given name, or null if none found for this Owner.
653	     *
654	     * @param name to test
655	     * @return true if pet name is already in use
656	     */
657	    public Pet getPet(String name) {
658	        return getPet(name, false);
659	    }
660	
661	    /**
662	     * Return the Pet with the given name, or null if none found for this Owner.
663	     *
664	     * @param name to test
665	     * @return true if pet name is already in use
666	     */
667	    public Pet getPet(String name, boolean ignoreNew) {
668	        name = name.toLowerCase();
669	        for (Pet pet : getPetsInternal()) {
670	            if (!ignoreNew || !pet.isNew()) {
671	                String compName = pet.getName();
672	                compName = compName.toLowerCase();
673	                if (compName.equals(name)) {
674	                    return pet;
675	                }
676	            }
677	        }
678	        return null;
679	    }
680	
681	    public Pet getPet(Integer petId) {
682	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
683	    }
684	
685	    @Override
686	    public String toString() {
687	        return new ToStringCreator(this)
688	
689	            .append("id", this.getId())
690	            .append("new", this.isNew())
691	            .append("lastName", this.getLastName())
692	            .append("firstName", this.getFirstName())
693	            .append("address", this.address)
694	            .append("city", this.city)
695	            .append("telephone", this.telephone)
696	            .append("email", this.email)
697	            .toString();
698	    }
699	}
