26	import java.util.List;
27	import java.util.Objects;
28	import java.util.Set;
29	import java.util.stream.Collectors;
30	
31	import org.slf4j.Logger;
32	import org.slf4j.LoggerFactory;
33	import org.springframework.http.HttpHeaders;
34	import org.springframework.http.HttpStatus;
35	import org.springframework.http.ResponseEntity;
36	import org.springframework.samples.petclinic.mapper.OwnerMapper;
37	import org.springframework.samples.petclinic.mapper.PetMapper;
38	import org.springframework.samples.petclinic.mapper.VisitMapper;
39	import org.springframework.samples.petclinic.model.Owner;
40	import org.springframework.samples.petclinic.model.Pet;
41	import org.springframework.samples.petclinic.model.Visit;
42	import org.springframework.samples.petclinic.rest.api.OwnersApi;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    private final AddressNormalizer addressNormalizer;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper,
83	                                 AddressNormalizer addressNormalizer) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	        this.addressNormalizer = addressNormalizer;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	
121	        HttpStatus invalid = normalizeAndValidate(owner);
122	        if (invalid != null) {
123	            return new ResponseEntity<>(invalid);
124	        }
125	        if (isDailyLimitReached(owner.getRegistrationDate())) {
126	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
127	        }
128	
129	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
130	        assignHousehold(owner);
131	
132	        HttpStatus conflict = checkForConflicts(owner, sharesHousehold);
133	        if (conflict != null) {
134	            return new ResponseEntity<>(conflict);
135	        }
136	
137	        assignDerivedAttributes(owner, sharesHousehold);
138	        this.clinicService.saveOwner(owner);
139	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
140	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
141	            owner.getMembershipLevel(), owner.getMembershipNumber());
142	        return created(owner);
143	    }
144	
145	    /**
146	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
147	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
148	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
149	     * postcode is checked against its city's region, a registration date in the future is rejected,
150	     * and the effective registration date (the supplied one, or today when none was given) is rolled
151	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
152	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
153	     * otherwise.
154	     */
155	    private HttpStatus normalizeAndValidate(Owner owner) {
156	        if (!normalizeAddress(owner)) {
157	            return HttpStatus.BAD_REQUEST;
158	        }
159	        String telephone = toE164(owner.getTelephone());
160	        if (telephone == null) {
161	            return HttpStatus.BAD_REQUEST;
162	        }
163	        owner.setTelephone(telephone);
164	        if (isDisposableEmail(owner.getEmail())) {
165	            return HttpStatus.BAD_REQUEST;
166	        }
167	        if (!owner.isPostcodeValid()) {
168	            return HttpStatus.BAD_REQUEST;
169	        }
170	        if (owner.getRegistrationDate() != null
171	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
172	            return HttpStatus.BAD_REQUEST;
173	        }
174	        LocalDate effectiveDate = owner.getRegistrationDate() != null
175	            ? owner.getRegistrationDate() : LocalDate.now();
176	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
177	        return null;
178	    }
179	
180	    /**
181	     * Normalize the owner's supplied address into its canonical stored form and report whether an
182	     * address was supplied at all. The owner may supply its address either as the structured
183	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
184	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
185	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
186	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
187	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
188	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
189	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
190	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
191	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
192	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
193	     * create must be rejected with {@code 400 Bad Request}.
194	     */
195	    private boolean normalizeAddress(Owner owner) {
196	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
197	        if (!line1.isEmpty()) {
198	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
199	            owner.setAddressLine1(line1);
200	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
201	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
202	            return true;
203	        }
204	        String address = addressNormalizer.normalize(owner.getAddress());
205	        if (address.isEmpty()) {
206	            return false;
207	        }
208	        owner.setAddressLine1(null);
209	        owner.setAddressLine2(null);
210	        owner.setAddress(address);
211	        return true;
212	    }
213	
214	    /**
215	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
216	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
217	     */
218	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
219	        "mailinator.com", "tempmail.com", "guerrillamail.com");
220	
221	    /**
222	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
223	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
224	     * the domain (the part after the last {@code '@'}, compared case-insensitively) is matched
225	     * against the blocklist.
226	     */
227	    private boolean isDisposableEmail(String email) {
228	        if (email == null || email.isEmpty()) {
229	            return false;
230	        }
231	        int at = email.lastIndexOf('@');
232	        if (at < 0) {
233	            return false;
234	        }
235	        String domain = email.substring(at + 1).toLowerCase();
236	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
237	    }
238	
239	    /**
240	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
241	     * deterministically from the owner's lastName and postcode, so every owner sharing that
242	     * lastName and postcode is assigned the same value automatically, independent of whether the
243	     * owner declares it shares a household. The link is assigned before the
244	     * {@link #checkForConflicts(Owner, boolean) conflict checks} because it is part of the owner's
245	     * {@link Owner#getIdentityKey() identity} and feeds its {@link #householdSize(String) household
246	     * size}.
247	     */
248	    private void assignHousehold(Owner owner) {
249	        owner.setHouseholdId(householdId(owner));
250	    }
251	
252	    /**
253	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
254	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
255	     * {@link #isHouseholdDuplicate(Owner) duplicates an existing household} or when its
256	     * {@link #isCityAtCapacity(String) city is already at capacity}. Declaring {@code
257	     * sharesHousehold} bypasses only the household-duplicate block (the owner is then created as a
258	     * declared household member); it does not lift the city-capacity limit. Returns {@code null}
259	     * when the owner clashes with nothing and may be created.
260	     */
261	    private HttpStatus checkForConflicts(Owner owner, boolean sharesHousehold) {
262	        if (!sharesHousehold && isHouseholdDuplicate(owner)) {
263	            return HttpStatus.CONFLICT;
264	        }
265	        if (isCityAtCapacity(owner.getCity())) {
266	            return HttpStatus.CONFLICT;
267	        }
268	        return null;
269	    }
270	
271	    /**
272	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
273	     * {@code Location} header pointing at {@code /api/owners/{id}}.
274	     */
275	    private ResponseEntity<OwnerDto> created(Owner owner) {
276	        HttpHeaders headers = new HttpHeaders();
277	        headers.setLocation(UriComponentsBuilder.newInstance()
278	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
279	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
280	    }
281	
282	    /**
283	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
284	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
285	     * {@link #isBulkSignup(LocalDate) bulk-signup warning} and {@link #householdSize(String)
286	     * householdSize}. Each is computed from the owner's own fields together with the owners already
287	     * present, so this runs after the owner has been validated and has passed the duplicate and
288	     * capacity checks, and immediately before it is persisted.
289	     */
290	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
291	        owner.setCustomerCode(customerCode(owner));
292	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
293	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
294	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
295	        assignPossibleDuplicate(owner, sharesHousehold);
296	    }
297	
298	    /**
299	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
300	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
301	     * so it is never flagged. Otherwise, because this runs after the hard
302	     * {@link #isHouseholdDuplicate(Owner) household-duplicate} check, the owner is not a household
303	     * match; it is flagged only when it is a soft match of an existing owner as determined by
304	     * {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
305	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
306	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
307	     */
308	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
309	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
310	        owner.setPossibleDuplicate(match != null);
311	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
312	    }
313	
314	    /**
315	     * The owners a newly created owner is checked against by the duplicate and identity rules:
316	     * the {@link #isHouseholdDuplicate(Owner) household-duplicate} and {@link #findSoftDuplicate(Owner)
317	     * soft-duplicate} checks, the {@link #customerCode(Owner) customerCode} de-duplication and the
318	     * {@link #namesakeCount(String, String) namesake} count. This is the single place that scope is
319	     * defined, so every one of those rules considers exactly the same set of owners; it currently
320	     * spans every owner the clinic holds.
321	     */
322	    private Collection<Owner> activeOwners() {
323	        return this.clinicService.findAllOwners();
324	    }
325	
326	    /**
327	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
328	     * match is an existing owner that shares this owner's lastName (compared case-insensitively,
329	     * with collapsed whitespace) and its postcode but carries a different telephone; the earliest
330	     * such owner (by id) is returned. A postcode is required for a soft match, so an owner without a
331	     * postcode never matches.
332	     */
333	    private Owner findSoftDuplicate(Owner owner) {
334	        if (owner.getPostcode() == null) {
335	            return null;
336	        }
337	        String candidateLastName = normalizeName(owner.getLastName());
338	        return activeOwners().stream()
339	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
340	            .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
341	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
342	            .min(Comparator.comparingInt(Owner::getId))
343	            .orElse(null);
344	    }
345	
346	    /**
347	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
348	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
349	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
350	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
351	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
352	     * every value built from the customer code (the membership number and its check digit) and the
353	     * owner's locality are derived from it.
354	     *
355	     * <p>When the computed code collides with an existing owner's {@code customerCode}, a
356	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the code
357	     * unique, and the de-duplicated code is returned.
358	     */
359	    private String customerCode(Owner owner) {
360	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
361	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
362	        String base = region + "-" + hash8;
363	
364	        Set<String> existingCodes = activeOwners().stream()
365	            .map(Owner::getCustomerCode)
366	            .filter(Objects::nonNull)
367	            .collect(Collectors.toSet());
368	
369	        if (!existingCodes.contains(base)) {
370	            return base;
371	        }
372	        int n = 2;
373	        while (existingCodes.contains(base + "-" + n)) {
374	            n++;
375	        }
376	        return base + "-" + n;
377	    }
378	
379	    /**
380	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
381	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
382	     * (business-day) registration date of the owner being created, so owners are counted per
383	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
384	     */
385	    private boolean isDailyLimitReached(LocalDate day) {
386	        long count = this.clinicService.findAllOwners().stream()
387	            .filter(existing -> day.equals(existing.getRegistrationDate()))
388	            .count();
389	        return count >= 100;
390	    }
391	
392	    /**
393	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
394	     * more than 80 owners have already been created for the given business day. Counts the owners
395	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
396	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
397	     * warning.
398	     */
399	    private boolean isBulkSignup(LocalDate day) {
400	        long count = this.clinicService.findAllOwners().stream()
401	            .filter(existing -> day.equals(existing.getRegistrationDate()))
402	            .count();
403	        return count > 80;
404	    }
405	
406	    /**
407	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
408	     * advance it to the following Monday; a weekday is returned unchanged.
409	     */
410	    private LocalDate toBusinessDay(LocalDate date) {
411	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
412	            date = date.plusDays(1);
413	        }
414	        return date;
415	    }
416	
417	    /**
418	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
419	     * more owners. Cities are compared case-insensitively.
420	     */
421	    private boolean isCityAtCapacity(String city) {
422	        long count = this.clinicService.findAllOwners().stream()
423	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
424	            .count();
425	        return count >= 50;
426	    }
427	
428	    /**
429	     * The number of existing owners that already share the given firstName and lastName,
430	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
431	     * whitespace runs collapsed). Counted over the owners present before this create.
432	     */
433	    private int namesakeCount(String firstName, String lastName) {
434	        String candidateFirstName = normalizeName(firstName);
435	        String candidateLastName = normalizeName(lastName);
436	        return (int) activeOwners().stream()
437	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
438	                && normalizeName(existing.getLastName()).equals(candidateLastName))
439	            .count();
440	    }
441	
442	    /**
443	     * The number of members in this owner's household after this create: the count of existing
444	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
445	     * created. An owner with no household ({@code householdId == null}) is a household of one.
446	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
447	     * does not depend on the order in which household members were created.
448	     */
449	    private int householdSize(String householdId) {
450	        if (householdId == null) {
451	            return 1;
452	        }
453	        long existing = this.clinicService.findAllOwners().stream()
454	            .filter(other -> householdId.equals(other.getHouseholdId()))
455	            .count();
456	        return (int) existing + 1;
457	    }
458	
459	    /**
460	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
461	     * cannot form a valid E.164 number.
462	     *
463	     * <p>A leading '+' and country code are kept when present; otherwise country code
464	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
465	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
466	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
467	     * exactly the national-digit count that code requires (see
468	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
469	     */
470	    private String toE164(String telephone) {
471	        if (telephone == null) {
472	            return null;
473	        }
474	        boolean hasCountryCode = telephone.trim().startsWith("+");
475	        String digits = telephone.replaceAll("\\D", "");
476	        String e164;
477	        if (hasCountryCode) {
478	            e164 = digits;
479	        } else {
480	            if (digits.startsWith("0")) {
481	                digits = digits.substring(1);
482	            }
483	            e164 = "61" + digits;
484	        }
485	        if (e164.length() < 8 || e164.length() > 15) {
486	            return null;
487	        }
488	        if (!Owner.hasValidNationalLength(e164)) {
489	            return null;
490	        }
491	        return "+" + e164;
492	    }
493	
494	    /**
495	     * Whether the candidate owner belongs to a household that already exists, and so must be
496	     * rejected with {@code 409 Conflict} unless it declares {@code sharesHousehold}. The household
497	     * is keyed by the deterministic {@link #householdId(Owner) householdId} (derived from lastName
498	     * and postcode), so any existing owner carrying the same householdId means this owner is a
499	     * second member of an already-registered household. Two owners sharing a lastName and postcode
500	     * are therefore the same household: the second is a household duplicate.
501	     */
502	    private boolean isHouseholdDuplicate(Owner owner) {
503	        String householdId = owner.getHouseholdId();
504	        if (householdId == null) {
505	            return false;
506	        }
507	        return activeOwners().stream()
508	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
509	    }
510	
511	    /**
512	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
513	     * to a single space and lower-case. A null value normalizes to the empty string.
514	     */
515	    private String normalizeName(String value) {
516	        if (value == null) {
517	            return "";
518	        }
519	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
520	    }
521	
522	    /**
523	     * A stable shared identifier for the household an owner belongs to, derived deterministically
524	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
525	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
526	     * assigned the same value regardless of the order in which they are created. Formatted as the
527	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
528	     * (an absent postcode contributes the empty string).
529	     */
530	    private String householdId(Owner owner) {
531	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
532	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
533	        return shaHexUpper(key).substring(0, 12);
534	    }
535	
536	    /**
537	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
538	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
539	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
540	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
541	     * {@link #customerCode} keeps the first 8).
542	     */
543	    private String shaHexUpper(String input) {
544	        try {
545	            byte[] digest = MessageDigest.getInstance("SHA-256")
546	                .digest(input.getBytes(StandardCharsets.UTF_8));
547	            StringBuilder sb = new StringBuilder(digest.length * 2);
548	            for (byte b : digest) {
549	                sb.append(String.format("%02x", b));
550	            }
551	            return sb.toString().toUpperCase();
552	        }
553	        catch (NoSuchAlgorithmException e) {
554	            throw new IllegalStateException("SHA-256 not available", e);
555	        }
556	    }
557	
558	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
559	    @Override
560	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
561	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
562	        if (currentOwner == null) {
563	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
564	        }
565	        currentOwner.setAddress(ownerFieldsDto.getAddress());
566	        currentOwner.setCity(ownerFieldsDto.getCity());
567	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
568	        currentOwner.setLastName(ownerFieldsDto.getLastName());
569	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
570	        this.clinicService.saveOwner(currentOwner);
571	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
572	    }
573	
574	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
575	    @Transactional
576	    @Override
577	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
578	        Owner owner = this.clinicService.findOwnerById(ownerId);
579	        if (owner == null) {
580	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
581	        }
582	        this.clinicService.deleteOwner(owner);
583	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
584	    }
585	
586	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
587	    @Override
588	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
589	        Owner owner = this.clinicService.findOwnerById(ownerId);
590	        if (owner == null) {
591	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
592	        }
593	        HttpHeaders headers = new HttpHeaders();
594	        Pet pet = petMapper.toPet(petFieldsDto);
595	        owner.setId(ownerId);
596	        pet.setOwner(owner);
597	        pet.getType().setName(null);
598	        this.clinicService.savePet(pet);
599	        PetDto petDto = petMapper.toPetDto(pet);
600	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
601	            .buildAndExpand(pet.getId()).toUri());
602	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
603	    }
604	
605	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
606	    @Override
607	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
608	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
609	        if (currentOwner != null) {
610	            Pet currentPet = this.clinicService.findPetById(petId);
611	            if (currentPet != null) {
612	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
613	                currentPet.setName(petFieldsDto.getName());
614	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
615	                this.clinicService.savePet(currentPet);
616	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
617	            }
618	        }
619	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
620	    }
621	
622	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
623	    @Override
624	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
625	        HttpHeaders headers = new HttpHeaders();
626	        Visit visit = visitMapper.toVisit(visitFieldsDto);
627	        Pet pet = new Pet();
628	        pet.setId(petId);
629	        visit.setPet(pet);
630	        this.clinicService.saveVisit(visit);
631	        VisitDto visitDto = visitMapper.toVisitDto(visit);
632	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
633	            .buildAndExpand(visit.getId()).toUri());
634	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
635	    }
636	
637	
638	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
639	    @Override
640	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
641	        Owner owner = this.clinicService.findOwnerById(ownerId);
642	        if (owner != null) {
643	            Pet pet = owner.getPet(petId);
644	            if (pet != null) {
645	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
646	            }
647	        }
648	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
649	    }
650	}
